import java.io.*;
import java.util.*;

public class Main {
    private static final InputStream IN = System.in;
    private static final byte[] BUF = new byte[1 << 16];
    private static int len = 0, ptr = 0;

    private static int read() throws IOException {
        if (ptr == len) {
            len = IN.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    private static int skipSpaces() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        return c;
    }

    private static long nextLong() throws IOException {
        int c = skipSpaces();
        boolean negative = c == '-';
        if (negative) c = read();
        long value = 0;
        while (c >= '0' && c <= '9') {
            value = value * 10 + (c - '0');
            c = read();
        }
        return negative ? -value : value;
    }

    private static int nextInt() throws IOException {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt(), m = nextInt(), q = nextInt();
        long[] a = new long[n];
        for (int i = 0; i < n; i++) a[i] = nextLong();
        long[] diff = new long[n + 1];
        for (int i = 0; i < m; i++) {
            int l = nextInt(), r = nextInt();
            diff[l]++;
            diff[r + 1]--;
        }
        // Pack (value, coverage count) into one long so a primitive sort orders by value; count < 2^20.
        long[] pairs = new long[n];
        long count = 0;
        for (int i = 0; i < n; i++) {
            count += diff[i];
            pairs[i] = (a[i] << 20) | count;
        }
        Arrays.sort(pairs);
        long[] values = new long[n], prefix = new long[n + 1];
        for (int i = 0; i < n; i++) {
            values[i] = pairs[i] >> 20;
            prefix[i + 1] = prefix[i] + (pairs[i] & ((1 << 20) - 1));
        }
        StringBuilder out = new StringBuilder();
        for (int i = 0; i < q; i++) {
            long t = nextLong();
            int lo = 0, hi = n; // first index with values[index] >= t
            while (lo < hi) {
                int mid = (lo + hi) >>> 1;
                if (values[mid] < t) lo = mid + 1;
                else hi = mid;
            }
            if (i > 0) out.append(' ');
            out.append(prefix[lo]);
        }
        System.out.println(out);
    }
}

package main

import (
	"bufio"
	"io"
	"os"
	"slices"
	"strconv"
)

var data []byte
var pos int

// next returns the next whitespace-separated token of the input.
func next() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int {
	token := next()
	negative := len(token) > 0 && token[0] == '-'
	if negative {
		token = token[1:]
	}
	value := 0
	for _, c := range token {
		value = value*10 + int(c-'0')
	}
	if negative {
		return -value
	}
	return value
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n, m, q := nextInt(), nextInt(), nextInt()
	a := make([]int, n)
	for i := range a {
		a[i] = nextInt()
	}
	diff := make([]int, n+1)
	for i := 0; i < m; i++ {
		l, r := nextInt(), nextInt()
		diff[l]++
		diff[r+1]--
	}
	// Pack (value, coverage count) into one int so sorting orders by value; count < 2^20.
	pairs := make([]int, n)
	count := 0
	for i := 0; i < n; i++ {
		count += diff[i]
		pairs[i] = a[i]<<20 | count
	}
	slices.Sort(pairs)
	values, prefix := make([]int, n), make([]int, n+1)
	for i, p := range pairs {
		values[i] = p >> 20
		prefix[i+1] = prefix[i] + p&(1<<20-1)
	}
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	for i := 0; i < q; i++ {
		t := nextInt()
		index, _ := slices.BinarySearch(values, t)
		if i > 0 {
			w.WriteByte(' ')
		}
		w.WriteString(strconv.Itoa(prefix[index]))
	}
	w.WriteByte('\n')
}
